static int perf_kvm__mmap_read ( struct perf_kvm_stat * kvm ) { int i , err , throttled = 0 ; s64 n , ntotal = 0 ; u64 flush_time = ULLONG_MAX , mmap_time ; for ( i = 0 ; i < kvm -> evlist -> core . nr_mmaps ; i ++ ) { n = perf_kvm__mmap_read_idx ( kvm , i , & mmap_time ) ; if ( mmap_time < flush_time ) { flush_time = mmap_time ; } ntotal += n ; if ( n == PERF_KVM__MAX_EVENTS_PER_MMAP ) { throttled = 1 ; } } if ( ntotal ) { struct ordered_events * oe = & kvm -> session -> ordered_events ; oe -> next_flush = flush_time ; err = ordered_events__flush ( oe , OE_FLUSH__ROUND ) ; if ( err ) { if ( kvm -> lost_events ) { pr_info ( "\nLost events: %" PRIu64 "\n\n" , kvm -> lost_events ) ; } return err ; } } return throttled ; } 